const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResult {
  results: QuoteResult[];
}

function itemBasePremium(item: Item): number {
  return BASE_PREMIUMS[item.type];
}

function quotePremium(step: QuoteStep): number {
  const policyBase = step.items.reduce((sum, item) => sum + itemBasePremium(item), 0);
  const withFirstInsurance = policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
  return Math.ceil(withFirstInsurance + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioResult {
  const results = scenario.steps.map((step) => ({ premium: quotePremium(step) }));
  return { results };
}

