const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(["rune"]);

function isComponent(type: string): boolean {
  return COMPONENT_TYPES.has(type);
}

function componentBase(count: number): number {
  const blocks = Math.floor(count / BLOCK_SIZE);
  const loose = count % BLOCK_SIZE;
  return blocks * BLOCK_BASE_PREMIUM + loose * COMPONENT_BASE_PREMIUM;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResult {
  results: QuoteResult[];
}

function componentCountsByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    if (isComponent(item.type)) {
      counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
    }
  }
  return counts;
}

function mainItemsBase(items: Item[]): number {
  return items
    .filter((item) => !isComponent(item.type))
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
}

function componentsBase(items: Item[]): number {
  let total = 0;
  for (const count of componentCountsByType(items).values()) {
    total += componentBase(count);
  }
  return total;
}

function policyBasePremium(items: Item[]): number {
  return mainItemsBase(items) + componentsBase(items);
}

function quotePremium(step: QuoteStep): number {
  const policyBase = policyBasePremium(step.items);
  const withFirstInsurance = policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
  return Math.ceil(withFirstInsurance + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioResult {
  const results = scenario.steps.map((step) => ({ premium: quotePremium(step) }));
  return { results };
}

