  const surcharges = itemSurcharges(step.items);
  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE;
  const total = policyBase + surcharges + firstInsurance + PROCESSING_FEE;
  return Math.ceil(total);
}

export function runScenario(scenario: Scenario): ScenarioResult {
  const results = scenario.steps.map((step) => ({ premium: quotePremium(step) }));
