import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Premium: base prices & processing fee ---
  it("empty item list -> premium 5 G (only processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });
    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("single sword, newcomer -> base 100 + first-insurance 10 + fee 5 = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("single amulet, newcomer -> base 60 + 6 + 5 = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("single staff, newcomer -> base 80 + 8 + 5 = 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("single potion, newcomer -> base 40 + 4 + 5 = 49 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Components & building blocks ---
  it("1 rune, newcomer -> base 25 + 2.5 + 5 = 32.5 -> ceil 33 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it("2 runes, newcomer -> base 50 + 5 + 5 = 60 G (no block)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes, newcomer -> block base 60 + 6 + 5 = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes, newcomer -> base 100 (no block) + 10 + 5 = 115 G", () => {
    const items = [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }];
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items }],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes, newcomer -> base 175 + 17.5 + 5 = 197.5 -> ceil 198 G", () => {
    const items = Array.from({ length: 7 }, () => ({ type: "rune" }));
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items }],
    });
    expect(result).toEqual({ results: [{ premium: 198 }] });
  });
  it("2 runes + 1 moonstone, newcomer -> base 75 + 7.5 + 5 = 87.5 -> 88 G", () => {
    const items = [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }];
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items }],
    });
    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 runes + 3 moonstones, newcomer -> base 120 (two blocks) + 12 + 5 = 137 G", () => {
    const items = [
      { type: "rune" }, { type: "rune" }, { type: "rune" },
      { type: "moonstone" }, { type: "moonstone" }, { type: "moonstone" },
    ];
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items }],
    });
    expect(result).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Item-specific premium modifiers ---
  it("cursed sword, newcomer -> 100 + 50 curse + 10 first = 160 + 5 = 165 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", cursed: true }] }],
    });
    expect(result).toEqual({ results: [{ premium: 165 }] });
  });
  it("sword enchantment 5, newcomer -> 100 + 30 high-ench + 10 first + 5 = 145 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", enchantment: 5 }] }],
    });
    expect(result).toEqual({ results: [{ premium: 145 }] });
  });
  it("sword enchantment 4, newcomer -> no high-ench surcharge -> 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", enchantment: 4 }] }],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("sword enchantment 5 and cursed, newcomer -> 100 + 50 + 30 + 10 + 5 = 195 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", enchantment: 5, cursed: true }] }],
    });
    expect(result).toEqual({ results: [{ premium: 195 }] });
  });

  // --- Policy-wide premium modifiers ---
  it("long-standing customer (2 years), plain sword -> 100 - 20 + 10 + 5 = 95 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 2 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 95 }] });
  });
  it.todo("first insurance -> 10% initial assessment surcharge on policy base");
  it.todo("each contract after the first -> 15% follow-up discount on policy base");
  it.todo("each item in a quote treated as first insurance regardless of customer history");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword (100) + plain amulet (60) -> 210 G before further modifiers and fee");

  // --- Rounding ---
  it.todo("premium calc yielding 197.5 G -> final premium 198 G (rounded up)");

  // --- Integration examples ---
  it.todo("newcomer with cursed sword (steel, ench 3) -> premium 165 G");
  it.todo("long-standing customer's second contract, cursed sword ench 7 -> premium 160 G");

  // --- Quote validation ---
  it.todo("quote with unknown item type (broomstick) -> CLI exits non-zero, error on stderr, no results");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, ench 3), damage 500 -> payout 400 (minus 100 deductible)");
  it.todo("damage to a rune (value 250), damage 200 -> payout 100 (minus deductible)");

  // --- Claim: special clauses ---
  it.todo("item enchantment >=8 -> damage reimbursed at 50%");
  it.todo("dragon material -> full reimbursement");
  it.todo("dragon-material sword ench 8, damage 1000 -> payout 400 (50% then deductible)");
  it.todo("dragon-material sword ench 9, damage 1000 -> payout 400 (50% wins, then deductible)");
  it.todo("dragon-material sword ench 5, damage 800 -> payout 700 (dragon full, then deductible)");
  it.todo("steel sword ench 9, damage 1000 -> payout 400 (high-ench 50%, then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages sword (500) and amulet (300) -> payout 600 (deductible once per item)");

  // --- Claim: cap ---
  it.todo("policy sword+amulet -> insurance sum 1600, cap 3200");
  it.todo("cursed sword -> cap 2000 (based on unmodified insurance value)");
  it.todo("policy sword + 3 runes block -> insurance sum 1750 (block discount not on sum)");
  it.todo("two swords -> insurance sum 2000, cap 4000; both damaged separate deductibles");
  it.todo("sword cap 2000; two claims of 1500 each -> first payout 1400 remaining 600; second payout 600 remaining 0");

  // --- Claim: rounding ---
  it.todo("payout calc yielding 350.5 G -> final payout 350 G (rounded down)");

  // --- Claim validation ---
  it.todo("damages has more entries of a type than covered -> CLI exits non-zero, claim rejected");
  it.todo("claim references item not part of policy (amulet when only sword) -> CLI exits non-zero, error on stderr");
  it.todo("claim with unknown item type -> CLI exits non-zero, error on stderr");
  it.todo("claim with damage amount -200 -> CLI exits non-zero, error on stderr");
});

